import 'bootstrap/dist/css/bootstrap.min.css';
import React from "react";
import './MainDashboard.css';

function MainDashboard() {
    const cardsData = [
        { icon: "👥", title: "Total Users", value: "1,247" },
        { icon: "✅", title: "Active Users", value: "1,108" },
        { icon: "📈", title: "Last Month", value: "2,080" },
        { icon: "🆕", title: "New This Month", value: "890" },
        { icon: "💰", title: "Revenue", value: "$12,450" },
        { icon: "📊", title: "Projects Completed", value: "76" },
        { icon: "⚡", title: "Tasks Pending", value: "32" },
        { icon: "⭐", title: "Customer Rating", value: "4.8/5" },
    ];

    return (
        <div className="dashboard-container">
            {/* Header */}
            <header className="dashboard-header">
                <div className="header-left">
                    <h1 className="header-title">Dashboard</h1>
                    <p className="header-subtitle">Welcome to your admin panel</p>
                </div>
                <div className="header-right">
                    <button className="header-btn">📅 Select Month</button>
                    <button className="header-btn">🔔 Notifications</button>
                    <div className="profile-avatar">A</div>
                </div>
            </header>

            {/* Dashboard Cards */}
            <main className="dashboard-main">
                <div className="dashboard-cards">
                    {cardsData.map((card, index) => (
                        <div className="card" key={index}>
                            <div className="card-icon">{card.icon}</div>
                            <div className="card-content">
                                <h3 className="card-title">{card.title}</h3>
                                <p className="card-value">{card.value}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </main>
        </div>
    );
}

export default MainDashboard;
